with v(k,q) as (values ('compressed_gas.1','oxygen fuel gas cylinders separate storage'),('flammable.0','flammable no smoking open flame'),('flammable.1','flammable liquid storage cabinet'),('fuel.0','fueling area turn off engine'),('fuel.1','fuel storage tank no smoking'),('noise.0','high noise area hearing protection'),('boiler.0','boiler room authorized personnel'),('boiler.1','hot surface do not touch pipes'),('mechanical_room.0','mechanical room authorized personnel only'),('confined.0','confined space permit required do not enter'),('fall.0','fall protection required beyond this point'),('fall.1','unprotected edge fall hazard'),('roof.0','roof access authorized personnel'),('excavation.0','open excavation trench keep back'),('scaffold.0','scaffold inspection tag'),('site_entry.0','construction site hard hat required'),('site_entry.1','construction site authorized personnel only'),('vehicles.0','watch for moving vehicles yard traffic'),('vehicles.1','yard speed limit'),('vehicle_lift.0','vehicle lift authorized operators only'),('vehicle_lift.1','stay clear raised vehicle lift'),('grain.0','grain bin entry engulfment'),('grain.1','grain auger moving parts')),
r as (select v.k, s.sku, row_number() over (partition by v.k order by s.score desc) rn from v cross join lateral finder.search_ids(v.q,null,null,null,null,10) s)
select r.k, r.rn, c.handle, left(c.title,90) t from r join lateral finder.cards(array[r.sku]) c on true where r.rn<=3 order by r.k, r.rn